import { SUPABASE_STORAGE_BUCKET } from "./supabase-config.js?v=fleet-sync-20260714";
import { fleet as publicFleet } from "./fleet-data.js?v=prestige-fleet-instant-20260812";

const root = document.querySelector("[data-fleet-operations]");
const nav = document.querySelector('[data-crm-section="vehicles"]');
const addButton = document.querySelector("[data-fleet-add]");
const calendarButton = document.querySelector("[data-fleet-calendar]");

const STATUS = { available:"Available", reserved:"Reserved", vehicle_out:"Vehicle Out", maintenance:"Maintenance", on_hold:"On Hold", partner_unavailable:"Partner Unavailable", inactive:"Inactive" };
const STATUS_FILTERS = ["available","reserved","vehicle_out","maintenance","on_hold","partner_unavailable","inactive"];
const CATEGORIES = ["Exotic","Luxury","SUV","Sports Car","Convertible","Sedan"];
const LOCATIONS = ["Prestige Luxor facility","Customer","Partner","Detail shop","Service center","Delivery","Other"];
const SERVICE_TYPES = ["Oil Service","Tires","Brakes","Alignment","Battery","Inspection","Repair","Detail","Other"];
const EXPENSE_TYPES = ["maintenance","repair","tires","detail","fuel","registration","insurance","transportation","parking","tolls","other"];
const DOC_TYPES = ["registration","insurance","lease_loan","partner_agreement","inspection","other"];

let data = { vehicles:[], role:"staff", period:{ key:"month" } };
let loaded = false;
let selected = null;
let detailData = { activity:[], mileage:[] };
let detailTab = "overview";
let view = localStorage.getItem("prestige-fleet-view") || "grid";
let calendarRange = Number(localStorage.getItem("prestige-fleet-calendar-range") || 14);
let filter = { search:"", ownership:"all", availability:"all", make:"all", category:"all", location:"all", maintenance:"all", documents:"all", active:"active" };
let period = "month";

const emptyMetrics = () => ({ status:"available", current_agreement:null, next_reservation:null, revenue:0, reservation_costs:0, general_expenses:0, gross_profit:0, net_profit:0, bookings:0, average_booking_value:0, document_warning:null, maintenance_warning:null });
function instantVehicles(){return (publicFleet||[]).map(car=>({...car,id:car.id,category_label:car.categoryLabel||car.category_label||car.category,ownership_type:"prestige",operational_status:"available",is_active:true,is_featured:true,current_mileage:null,current_location:"",image_url:car.image_url||car.image,photos:(car.gallery||[]).map((url,index)=>({url,position:index+1})),partner:null,agreements:[],blocks:[],expenses:[],maintenance:[],documents:[],metrics:emptyMetrics()}));}

const escapeHtml = (value) => String(value ?? "").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
const money = (value, decimals=0) => new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:decimals,minimumFractionDigits:decimals}).format(Number(value||0));
const number = (value) => new Intl.NumberFormat("en-US").format(Number(value||0));
const dateLabel = (value, time=false) => value ? new Date(value).toLocaleString("en-US", time ? {month:"short",day:"numeric",year:"numeric",hour:"numeric",minute:"2-digit"}:{month:"short",day:"numeric",year:"numeric"}) : "—";
const dateInput = (value) => value ? new Date(value).toISOString().slice(0,10) : "";
const localInput = (value) => { if(!value)return "";const d=new Date(value);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16); };
const today = () => new Date().toISOString().slice(0,10);
const vehicleTitle = (v) => [v.year,v.make,v.model,v.trim].filter(Boolean).join(" ") || v.name;
const partner = (v) => v.partner || {};
const statusBadge = (status) => `<span class="fleet-status ${escapeHtml(status)}">${escapeHtml(STATUS[status]||status)}</span>`;
const ownershipBadge = (v) => `<span class="fleet-ownership ${v.ownership_type}">${v.ownership_type==="partner"?"Partner Vehicle":"Prestige Owned"}</span>`;
const daysUntil = (value) => value ? Math.ceil((new Date(`${value}T23:59:59`)-new Date())/86400000) : Infinity;

function toast(message,tone="success") { let n=document.querySelector("[data-fleet-toast]");if(!n){n=document.createElement("div");n.className="quote-toast fleet-toast";n.dataset.fleetToast="";n.setAttribute("role","status");document.body.append(n);}n.textContent=message;n.dataset.tone=tone;n.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove("show"),4200); }
async function authToken(){const session=(await window.prestigeLuxorSupabase?.auth.getSession())?.data?.session;if(!session?.access_token)throw new Error("Sign in again to manage Fleet.");return session.access_token;}
async function api(path="fleet",options={}){const response=await fetch(`/api/${path}`,{...options,headers:{Authorization:`Bearer ${await authToken()}`,...(options.body?{"Content-Type":"application/json"}:{}),...(options.headers||{})}});const payload=await response.json().catch(()=>({}));if(!response.ok){const message=payload.error||"Fleet request failed.";if(/vehicle_blocks|vehicle_expenses|vehicle_maintenance|vehicle_documents|operational_status|ownership_type/i.test(message)&&/schema|column|table|cache|not found/i.test(message))throw new Error("Fleet Operations needs its database migration. Run supabase/fleet-operations.sql, then retry.");throw new Error(message);}return payload;}

function visibleVehicles(){const q=filter.search.toLowerCase().trim();return data.vehicles.filter(v=>{const search=[vehicleTitle(v),v.name,v.make,v.model,v.year,v.license_plate,v.vin,v.internal_fleet_id,partner(v).partner_name].join(" ").toLowerCase();return(!q||search.includes(q))&&(filter.ownership==="all"||v.ownership_type===filter.ownership)&&(filter.availability==="all"||v.metrics.status===filter.availability)&&(filter.make==="all"||v.make===filter.make)&&(filter.category==="all"||v.category_label===filter.category)&&(filter.location==="all"||v.current_location===filter.location)&&(filter.active==="all"||(filter.active==="active"?v.is_active:!v.is_active))&&(filter.maintenance==="all"||(filter.maintenance==="due"?Boolean(v.metrics.maintenance_warning):v.metrics.status==="maintenance"))&&(filter.documents==="all"||(filter.documents==="expired"?v.documents.some(d=>daysUntil(d.expiration_date)<0):v.documents.some(d=>daysUntil(d.expiration_date)>=0&&daysUntil(d.expiration_date)<=30)));});}

function kpis(){const active=data.vehicles.filter(v=>v.is_active),now=Date.now(),week=now+7*86400000;const upcoming=active.filter(v=>v.metrics.next_reservation&&new Date(v.metrics.next_reservation.rental_start_at||v.metrics.next_reservation.rental_start).getTime()<=week).length;return `<div class="fleet-kpis"><article><span>Total Vehicles</span><strong>${active.length}</strong></article><article><span>Available Now</span><strong>${active.filter(v=>v.metrics.status==="available").length}</strong></article><article><span>Currently Rented</span><strong>${active.filter(v=>v.metrics.status==="vehicle_out").length}</strong></article><article><span>Upcoming</span><strong>${upcoming}</strong></article><article><span>Maintenance</span><strong>${active.filter(v=>v.metrics.status==="maintenance").length}</strong></article><article><span>Fleet Revenue</span><strong>${money(active.reduce((s,v)=>s+Number(v.metrics.revenue||0),0))}</strong></article></div>`;}

function toolbar(){const makes=[...new Set(data.vehicles.map(v=>v.make).filter(Boolean))].sort();const cats=[...new Set(data.vehicles.map(v=>v.category_label).filter(Boolean))].sort();const locations=[...new Set(data.vehicles.map(v=>v.current_location).filter(Boolean))].sort();return `<section class="fleet-toolbar"><div class="fleet-ownership-tabs" role="tablist" aria-label="Ownership filter">${[["all","All"],["prestige","Prestige Owned"],["partner","Partner"]].map(([id,label])=>`<button type="button" class="${filter.ownership===id?"active":""}" data-fleet-ownership="${id}">${label}</button>`).join("")}</div><div class="fleet-view-tabs" aria-label="Fleet view">${["grid","list","calendar"].map(id=>`<button type="button" class="${view===id?"active":""}" data-fleet-view="${id}">${id[0].toUpperCase()+id.slice(1)}</button>`).join("")}</div><label class="fleet-search"><span>Search fleet</span><input type="search" value="${escapeHtml(filter.search)}" placeholder="Make, model, plate, VIN, partner, or fleet ID" data-fleet-search></label><label><span>Availability</span><select data-fleet-filter="availability"><option value="all">All statuses</option>${STATUS_FILTERS.map(s=>`<option value="${s}" ${filter.availability===s?"selected":""}>${STATUS[s]}</option>`).join("")}</select></label><details class="fleet-more-filters"><summary>More filters</summary><div><label><span>Make</span><select data-fleet-filter="make"><option value="all">All makes</option>${makes.map(x=>`<option ${filter.make===x?"selected":""}>${escapeHtml(x)}</option>`).join("")}</select></label><label><span>Category</span><select data-fleet-filter="category"><option value="all">All categories</option>${cats.map(x=>`<option ${filter.category===x?"selected":""}>${escapeHtml(x)}</option>`).join("")}</select></label><label><span>Location</span><select data-fleet-filter="location"><option value="all">All locations</option>${locations.map(x=>`<option ${filter.location===x?"selected":""}>${escapeHtml(x)}</option>`).join("")}</select></label><label><span>Maintenance</span><select data-fleet-filter="maintenance"><option value="all">Any maintenance</option><option value="due" ${filter.maintenance==="due"?"selected":""}>Service due</option><option value="active" ${filter.maintenance==="active"?"selected":""}>In service</option></select></label><label><span>Documents</span><select data-fleet-filter="documents"><option value="all">Any document status</option><option value="expiring" ${filter.documents==="expiring"?"selected":""}>Expiring soon</option><option value="expired" ${filter.documents==="expired"?"selected":""}>Expired</option></select></label><label><span>Record status</span><select data-fleet-filter="active"><option value="active" ${filter.active==="active"?"selected":""}>Active only</option><option value="inactive" ${filter.active==="inactive"?"selected":""}>Archived</option><option value="all" ${filter.active==="all"?"selected":""}>All records</option></select></label></div></details></section>`;}

function warningChips(v){const chips=[];const doc=v.metrics.document_warning;if(doc){const days=daysUntil(doc.expiration_date);if(days<=30)chips.push(`<span class="fleet-warning ${days<0?"danger":""}">${escapeHtml(doc.document_type.replaceAll("_"," "))} ${days<0?"expired":`expires in ${days} days`}</span>`);}const m=v.metrics.maintenance_warning;if(m){if(m.next_service_mileage&&v.current_mileage)chips.push(`<span class="fleet-warning">${escapeHtml(m.service_type)} due in ${number(m.next_service_mileage-v.current_mileage)} mi</span>`);else if(m.next_service_date)chips.push(`<span class="fleet-warning">${escapeHtml(m.service_type)} due ${dateLabel(m.next_service_date)}</span>`);}return chips.join("");}
function gridView(vehicles){return vehicles.length?`<div class="fleet-card-grid">${vehicles.map(v=>`<article class="fleet-vehicle-card" tabindex="0" data-open-vehicle="${v.id}"><div class="fleet-card-media"><img src="${escapeHtml(v.image_url||v.photos[0]?.url||"/assets/prestige-luxor-hero.png")}" alt="${escapeHtml(vehicleTitle(v))}" width="720" height="440" loading="lazy"><div>${ownershipBadge(v)}${statusBadge(v.metrics.status)}</div></div><div class="fleet-card-body"><span>${escapeHtml(v.internal_fleet_id||v.category_label||"Fleet vehicle")}</span><h3>${escapeHtml(vehicleTitle(v))}</h3><dl><div><dt>Daily rate</dt><dd>${money(v.price)}/day</dd></div><div><dt>Mileage</dt><dd>${v.current_mileage==null?"Not recorded":`${number(v.current_mileage)} mi`}</dd></div><div><dt>Location</dt><dd>${escapeHtml(v.current_location||"—")}</dd></div><div><dt>Gross profit</dt><dd>${money(v.metrics.gross_profit)}</dd></div></dl>${v.metrics.next_reservation?`<p class="fleet-next"><span>Next Booking</span><strong>${dateLabel(v.metrics.next_reservation.rental_start_at||v.metrics.next_reservation.rental_start)}–${dateLabel(v.metrics.next_reservation.rental_end_at||v.metrics.next_reservation.rental_end)}</strong></p>`:`<p class="fleet-next"><span>Next Booking</span><strong>Open calendar</strong></p>`}<div class="fleet-card-warnings">${warningChips(v)}</div></div></article>`).join("")}</div>`:emptyState();}
function listView(vehicles){return vehicles.length?`<div class="crm-table-container fleet-table"><table><thead><tr><th>Vehicle</th><th>Year</th><th>Ownership</th><th>Plate</th><th>Mileage</th><th>Daily Rate</th><th>Status</th><th>Current/Next Reservation</th><th>Revenue</th><th>Gross Profit</th><th>Actions</th></tr></thead><tbody>${vehicles.map(v=>`<tr data-open-vehicle="${v.id}" tabindex="0"><td><div class="fleet-table-vehicle"><img src="${escapeHtml(v.image_url||v.photos[0]?.url||"/assets/prestige-luxor-hero.png")}" alt="" width="56" height="40"><strong>${escapeHtml([v.make,v.model,v.trim].filter(Boolean).join(" "))}</strong></div></td><td>${v.year||"—"}</td><td>${ownershipBadge(v)}</td><td>${escapeHtml(v.license_plate||"—")}</td><td>${v.current_mileage==null?"—":number(v.current_mileage)}</td><td>${money(v.price)}</td><td>${statusBadge(v.metrics.status)}</td><td>${v.metrics.current_agreement?`${escapeHtml(v.metrics.current_agreement.agreement_number)} · ${escapeHtml(v.metrics.current_agreement.customer_name)}`:v.metrics.next_reservation?`${escapeHtml(v.metrics.next_reservation.agreement_number)} · ${dateLabel(v.metrics.next_reservation.rental_start_at||v.metrics.next_reservation.rental_start)}`:"Available"}</td><td>${money(v.metrics.revenue)}</td><td>${money(v.metrics.gross_profit)}</td><td><button class="fleet-row-open" type="button" data-open-vehicle="${v.id}">Open</button></td></tr>`).join("")}</tbody></table></div>`:emptyState();}
function dateDays(count){const days=[];const base=new Date();base.setHours(0,0,0,0);for(let i=0;i<count;i++){const d=new Date(base);d.setDate(d.getDate()+i);days.push(d);}return days;}
function calendarView(vehicles){const days=dateDays(calendarRange);return `<section class="fleet-calendar-card"><header><div><h3>Availability Calendar</h3><p>Reservations and operational blocks use the same conflict source as Quotes.</p></div><div>${[[7,"Week"],[14,"2 Weeks"],[30,"Month"]].map(([n,l])=>`<button class="${calendarRange===n?"active":""}" data-calendar-range="${n}">${l}</button>`).join("")}</div></header><div class="fleet-calendar-scroll"><div class="fleet-calendar-grid" style="--days:${days.length}"><div class="fleet-calendar-corner">Vehicle</div>${days.map(d=>`<div class="fleet-calendar-day"><b>${d.toLocaleDateString("en-US",{weekday:"short"})}</b><span>${d.getDate()}</span></div>`).join("")}${vehicles.map(v=>`<div class="fleet-calendar-name" data-open-vehicle="${v.id}"><img src="${escapeHtml(v.image_url||v.photos[0]?.url||"/assets/prestige-luxor-hero.png")}" alt="" width="42" height="30"><span>${escapeHtml([v.make,v.model].filter(Boolean).join(" "))}</span></div>${days.map(d=>{const ds=d.toISOString(),de=new Date(d.getTime()+86400000).toISOString();const a=v.agreements.find(x=>!["cancelled","completed"].includes(x.status)&&new Date(x.rental_start_at||`${x.rental_start}T00:00:00`)<new Date(de)&&new Date(x.rental_end_at||`${x.rental_end}T23:59:59`)>new Date(ds));const b=v.blocks.find(x=>new Date(x.start_at)<new Date(de)&&new Date(x.end_at)>new Date(ds));const type=a?(a.status==="vehicle_out"?"vehicle_out":"reservation"):b?.block_type||"available";const label=a?a.agreement_number:b?.reason||"Available";return `<button class="fleet-calendar-cell ${type}" data-calendar-cell="${v.id}" data-date="${d.toISOString().slice(0,10)}" ${a?`data-open-reservation="${a.id}"`:""} aria-label="${escapeHtml(vehicleTitle(v))}, ${d.toDateString()}: ${escapeHtml(label)}"><span>${escapeHtml(label)}</span></button>`;}).join("")}`).join("")}</div></div><footer><span><i class="reservation"></i>Confirmed</span><span><i class="vehicle_out"></i>Vehicle out</span><span><i class="maintenance"></i>Maintenance</span><span><i class="manual_hold"></i>Manual hold</span><span><i class="partner_unavailable"></i>Partner unavailable</span></footer></section>`;}
function emptyState(){return `<div class="fleet-empty"><strong>No vehicles in your fleet</strong><p>Add a vehicle to start managing availability and reservations.</p><button class="primary-button" type="button" data-fleet-add-inline>Add Vehicle</button></div>`;}

function renderMain(){const vehicles=visibleVehicles();root.innerHTML=`${kpis()}${toolbar()}<div class="fleet-results-head"><span>${vehicles.length} of ${data.vehicles.length} vehicles</span><label>Financial period<select data-fleet-period><option value="month" ${period==="month"?"selected":""}>This Month</option><option value="last_month" ${period==="last_month"?"selected":""}>Last Month</option><option value="ytd" ${period==="ytd"?"selected":""}>YTD</option></select></label></div>${view==="list"?listView(vehicles):view==="calendar"?calendarView(vehicles):gridView(vehicles)}`;}

function detailTabs(v){return `<nav class="fleet-detail-tabs" aria-label="Vehicle details">${["overview","reservations","calendar","financials","maintenance","documents","activity"].map(id=>`<button class="${detailTab===id?"active":""}" data-vehicle-tab="${id}">${id[0].toUpperCase()+id.slice(1)}</button>`).join("")}</nav><div class="fleet-tab-content">${detailTab==="overview"?simpleOverviewTab(v):detailTab==="reservations"?reservationsTab(v):detailTab==="calendar"?vehicleCalendarTab(v):detailTab==="financials"?financialsTab(v):detailTab==="maintenance"?maintenanceTab(v):detailTab==="documents"?documentsTab(v):activityTab(v)}</div>`;}
function facts(items){return `<dl class="fleet-detail-facts">${items.map(([k,v])=>`<div><dt>${k}</dt><dd>${v||"—"}</dd></div>`).join("")}</dl>`;}
function overviewTab(v){const current=v.metrics.current_agreement;return `<div class="fleet-detail-columns"><main><section class="fleet-detail-card"><header><h4>Vehicle Information</h4><button data-fleet-action="edit">Edit</button></header>${facts([["Year",v.year],["Make",escapeHtml(v.make)],["Model",escapeHtml(v.model)],["Trim",escapeHtml(v.trim)],["Exterior",escapeHtml(v.color)],["Interior",escapeHtml(v.interior_color)],["VIN",escapeHtml(v.vin)],["Plate",escapeHtml([v.license_plate,v.registration_state].filter(Boolean).join(" · "))],["Category",escapeHtml(v.category_label)]])}</section><section class="fleet-detail-card"><header><h4>Pricing Defaults</h4></header>${facts([["Daily rate",money(v.price)],["Weekend",v.weekend_rate?money(v.weekend_rate):"—"],["Weekly",v.weekly_rate?money(v.weekly_rate):"—"],["Included mileage",v.included_mileage?`${number(v.included_mileage)} mi/day`:escapeHtml(v.mileage)],["Extra mileage",money(v.extra_mileage_rate,2)+"/mi"],["Security deposit",money(v.security_deposit)],["Minimum rental",`${v.minimum_rental_days||1} day(s)`],["Partner daily cost",v.ownership_type==="partner"?money(partner(v).partner_daily_cost):"Not applicable"]])}</section></main><aside><section class="fleet-detail-card"><header><h4>Current Status</h4>${statusBadge(v.metrics.status)}</header>${facts([["Location",escapeHtml(v.current_location)],["Current customer",escapeHtml(current?.customer_name)],["Expected return",dateLabel(current?.rental_end_at||current?.rental_end)],["Next booking",v.metrics.next_reservation?`${escapeHtml(v.metrics.next_reservation.agreement_number)} · ${dateLabel(v.metrics.next_reservation.rental_start_at||v.metrics.next_reservation.rental_start)}`:"Open"],["Current mileage",v.current_mileage==null?"Not recorded":`${number(v.current_mileage)} mi`]])}<button class="secondary-button compact" data-fleet-action="mileage">Update Mileage</button></section><section class="fleet-detail-card attention"><header><h4>Needs Attention</h4></header>${warningChips(v)||"<p>No document or maintenance warnings.</p>"}</section></aside></div>`;}
function simpleOverviewTab(v){const current=v.metrics.current_agreement;return `<div class="fleet-detail-columns"><main><section class="fleet-detail-card"><header><h4>Vehicle Information</h4><button data-fleet-action="edit">Edit</button></header>${facts([["Vehicle",escapeHtml(v.name)],["Make",escapeHtml(v.make)],["Model",escapeHtml(v.model)],["Category",escapeHtml(v.category_label||v.category)],["Color",escapeHtml(v.color)],["Seats",v.seats]])}</section><section class="fleet-detail-card"><header><h4>Rental Defaults</h4></header>${facts([["Daily rate",money(v.price)],["Mileage allowance",escapeHtml(v.mileage)],["Ownership",v.ownership_type==="partner"?"Partner Vehicle":"Prestige Luxor"],["Partner",v.partner?escapeHtml(v.partner.partner_name):"Not applicable"]])}</section></main><aside><section class="fleet-detail-card"><header><h4>Current Status</h4>${statusBadge(v.metrics.status)}</header>${facts([["Current customer",escapeHtml(current?.customer_name)],["Expected return",dateLabel(current?.rental_end_at||current?.rental_end)],["Next booking",v.metrics.next_reservation?`${escapeHtml(v.metrics.next_reservation.agreement_number)} · ${dateLabel(v.metrics.next_reservation.rental_start_at||v.metrics.next_reservation.rental_start)}`:"Open"]])}</section></aside></div>`;}
function reservationsTab(v){return v.agreements.length?`<div class="crm-table-container fleet-detail-table"><table><thead><tr><th>Reservation #</th><th>Customer</th><th>Start</th><th>End</th><th>Revenue</th><th>Status</th></tr></thead><tbody>${v.agreements.sort((a,b)=>new Date(b.rental_start_at||b.rental_start)-new Date(a.rental_start_at||a.rental_start)).map(a=>`<tr data-open-reservation="${a.id}"><td><strong>${escapeHtml(a.agreement_number)}</strong></td><td>${escapeHtml(a.customer_name)}</td><td>${dateLabel(a.rental_start_at||a.rental_start)}</td><td>${dateLabel(a.rental_end_at||a.rental_end)}</td><td>${money(a.quote_total||a.rental_total)}</td><td>${escapeHtml(a.status.replaceAll("_"," "))}</td></tr>`).join("")}</tbody></table></div>`:`<div class="fleet-tab-empty"><strong>No reservations yet</strong><button class="primary-button compact" data-fleet-action="quote">Create Quote</button></div>`;}
function vehicleCalendarTab(v){return `<div class="fleet-tab-actions"><div><h3>${escapeHtml(vehicleTitle(v))} availability</h3><p>Reservations, maintenance, holds, and partner unavailability.</p></div><button class="primary-button compact" data-fleet-action="block">Block Dates</button></div>${calendarView([v])}<section class="fleet-detail-card"><header><h4>Blocked Dates</h4></header>${v.blocks.length?v.blocks.map(b=>`<div class="fleet-record-row"><div>${statusBadge(b.block_type==="manual_hold"?"on_hold":b.block_type)}<strong>${escapeHtml(b.reason||b.block_type.replaceAll("_"," "))}</strong><span>${dateLabel(b.start_at,true)} – ${dateLabel(b.end_at,true)}</span></div><button class="danger-button compact" data-delete-fleet-record="block" data-record-id="${b.id}">Remove</button></div>`).join(""):"<p>No manual or maintenance blocks.</p>"}</section>`;}
function financialsTab(v){const m=v.metrics,utilization=Math.min((v.agreements.reduce((s,a)=>s+(["signed","vehicle_out","returned","completed"].includes(a.status)?Number(a.rental_days||0):0),0)/Math.max(new Date(data.period.end)-new Date(data.period.start),86400000)*86400000)*100,100);return `<div class="fleet-finance-kpis"><article><span>Revenue</span><strong>${money(m.revenue)}</strong></article><article><span>Gross Rental Profit</span><strong>${money(m.gross_profit)}</strong></article><article><span>Net Vehicle Profit</span><strong>${money(m.net_profit)}</strong></article><article><span>Bookings</span><strong>${m.bookings}</strong></article><article><span>Avg. Booking Value</span><strong>${money(m.average_booking_value)}</strong></article><article><span>Utilization</span><strong>${utilization.toFixed(0)}%</strong></article></div><div class="fleet-detail-columns"><main><section class="fleet-detail-card"><header><h4>Reservation Profitability</h4><button data-fleet-action="expense">Add Expense</button></header>${v.agreements.length?`<div class="crm-table-container fleet-detail-table"><table><thead><tr><th>Reservation</th><th>Customer</th><th>Revenue</th><th>Costs</th><th>Profit</th></tr></thead><tbody>${v.agreements.map(a=>{const revenue=["draft","cancelled"].includes(a.status)?0:Number(a.quote_total||a.rental_total||0);const costs=Number(a.partner_cost||0)+(a.internal_costs||[]).reduce((s,i)=>s+Number(i.amount||0),0)+v.expenses.filter(e=>e.agreement_id===a.id).reduce((s,e)=>s+Number(e.amount||0),0);return `<tr data-open-reservation="${a.id}"><td>${escapeHtml(a.agreement_number)}</td><td>${escapeHtml(a.customer_name)}</td><td>${money(revenue)}</td><td>${money(costs)}</td><td>${money(revenue-costs)}</td></tr>`;}).join("")}</tbody></table></div>`:"<p>No reservation revenue in this period.</p>"}</section></main><aside><section class="fleet-detail-card"><header><h4>Cost Separation</h4></header>${facts([["Partner & reservation costs",money(m.reservation_costs)],["General operating expenses",money(m.general_expenses)],["Security deposits","Excluded from revenue"],["Partner payouts",v.ownership_type==="partner"?money(v.agreements.reduce((s,a)=>s+Number(a.partner_cost||0),0)):"Not applicable"]])}</section><section class="fleet-detail-card"><header><h4>Vehicle Expenses</h4></header>${v.expenses.length?v.expenses.map(e=>`<div class="fleet-record-row"><div><strong>${escapeHtml(e.category)}</strong><span>${dateLabel(e.expense_date)} · ${escapeHtml(e.expense_scope)}</span></div><b>${money(e.amount)}</b></div>`).join(""):"<p>No expenses recorded for this period.</p>"}</section></aside></div>`;}
function maintenanceTab(v){
  const records=v.maintenance.map((record)=>{
    const badgeStatus=record.status==="in_service"?"maintenance":record.status==="scheduled"?"reserved":"available";
    const mileage=record.mileage?`${number(record.mileage)} mi`:"Mileage not recorded";
    const nextDate=record.next_service_date?` · Next ${dateLabel(record.next_service_date)}`:"";
    const nextMileage=record.next_service_mileage?` · Next at ${number(record.next_service_mileage)} mi`:"";
    return `<div class="fleet-record-row"><div>${statusBadge(badgeStatus)}<strong>${escapeHtml(record.service_type)}</strong><span>${dateLabel(record.service_date)} · ${escapeHtml(record.vendor||"No vendor")} · ${mileage}</span><small>${escapeHtml(record.notes||"")}${nextDate}${nextMileage}</small></div><b>${money(record.cost)}</b></div>`;
  }).join("");
  const empty='<div class="fleet-tab-empty"><strong>No maintenance records</strong><p>Add service history and reminders for this vehicle.</p></div>';
  return `<div class="fleet-tab-actions"><div><h3>Maintenance</h3><p>Service schedule, current work, and history.</p></div><button class="primary-button compact" data-fleet-action="maintenance">Add Maintenance</button></div><section class="fleet-detail-card">${records||empty}</section>`;
}
function documentsTab(v){
  const documents=v.documents.map((documentRecord)=>{
    const days=daysUntil(documentRecord.expiration_date);
    const warning=days<=30?`<b class="${days<0?"expired":""}">${days<0?"Expired":`Expires in ${days} days`}</b>`:"";
    const open=documentRecord.file_path?`<button data-open-document="${escapeHtml(documentRecord.file_path)}">Open Document</button>`:"";
    return `<article><div><span>${escapeHtml(documentRecord.document_type.replaceAll("_"," "))}</span>${warning}</div><h4>${escapeHtml(documentRecord.file_name||"Document record")}</h4><p>Effective ${dateLabel(documentRecord.effective_date)}<br>Expires ${dateLabel(documentRecord.expiration_date)}</p>${open}</article>`;
  }).join("");
  const empty='<div class="fleet-tab-empty"><strong>No documents uploaded</strong><p>Add registration and insurance records to receive expiration warnings.</p></div>';
  return `<div class="fleet-tab-actions"><div><h3>Vehicle Documents</h3><p>Private staff-only registration, insurance, agreements, and inspections.</p></div><button class="primary-button compact" data-fleet-action="document">Add Document</button></div><section class="fleet-document-grid">${documents||empty}</section>`;
}
function activityTab(v){return `<section class="fleet-detail-card"><header><h4>Vehicle Activity</h4></header><ol class="fleet-activity">${detailData.activity.length?detailData.activity.map(a=>`<li><i></i><div><strong>${escapeHtml(a.action.replaceAll("_"," "))}</strong><span>${escapeHtml(a.detail)}</span><time>${dateLabel(a.created_at,true)}</time></div></li>`).join(""):"<li><i></i><div><strong>Vehicle record active</strong></div></li>"}</ol></section>`;}

function renderDetail(){const v=selected;root.innerHTML=`<div class="fleet-detail-nav"><button data-back-fleet>← All vehicles</button><div><button class="secondary-button compact" data-fleet-action="quote">Create Quote</button><button class="secondary-button compact" data-fleet-action="block">Block Dates</button><button class="secondary-button compact" data-fleet-action="expense">Add Expense</button><button class="secondary-button compact" data-fleet-action="maintenance">Add Maintenance</button><button class="primary-button compact" data-fleet-action="edit">Edit Vehicle</button></div></div><section class="fleet-detail-hero"><img src="${escapeHtml(v.image_url||v.photos[0]?.url||"/assets/prestige-luxor-hero.png")}" alt="${escapeHtml(vehicleTitle(v))}" width="1400" height="720"><div><p class="eyebrow">${escapeHtml(v.internal_fleet_id||"Vehicle profile")}</p><h2>${escapeHtml(vehicleTitle(v))}</h2><span>${ownershipBadge(v)}${statusBadge(v.metrics.status)}</span></div></section><div class="fleet-summary-strip">${[["Current status",STATUS[v.metrics.status]],["Daily rate",money(v.price)],["Current mileage",v.current_mileage==null?"—":number(v.current_mileage)+" mi"],["Plate",v.license_plate||"—"],["Location",v.current_location||"—"],["Next reservation",v.metrics.next_reservation?dateLabel(v.metrics.next_reservation.rental_start_at||v.metrics.next_reservation.rental_start):"Open"],["Revenue",money(v.metrics.revenue)],["Gross profit",money(v.metrics.gross_profit)]].map(([k,val])=>`<article><span>${k}</span><strong>${escapeHtml(val)}</strong></article>`).join("")}</div>${detailTabs(v)}`;}

async function openVehicle(id){const cached=data.vehicles?.find(vehicle=>String(vehicle.id)===String(id));if(cached){selected=cached;detailData={vehicle:cached,activity:[],mileage:[]};detailTab="overview";renderDetail();}else root.innerHTML=`<div class="crm-loading-state fleet-operations-loading">Loading vehicle profile…</div>`;try{const result=await api(`fleet?id=${encodeURIComponent(id)}&period=${period}`);if(selected&&String(selected.id)!==String(id))return;selected=result.vehicle;detailData=result;renderDetail();}catch(error){if(cached)return;root.innerHTML=`<div class="fleet-error"><strong>Vehicle could not be opened</strong><p>${escapeHtml(error.message)}</p><button class="secondary-button" data-back-fleet>Back to Fleet</button></div>`;}}

function ensureDialogs(){if(document.querySelector("[data-fleet-vehicle-dialog]"))return;document.body.insertAdjacentHTML("beforeend",`<dialog class="fleet-form-dialog" data-fleet-vehicle-dialog><form data-fleet-vehicle-form><header><div><p class="eyebrow">Fleet record</p><h2 data-fleet-form-title>Add Vehicle</h2><p>Vehicle details, ownership, pricing, photos, mileage and documents.</p></div><button type="button" data-close-fleet-dialog aria-label="Close">×</button></header><div class="fleet-form-scroll" data-fleet-form-fields></div><footer><p data-fleet-form-status role="status"></p><button class="secondary-button" type="button" data-close-fleet-dialog>Cancel</button><button class="primary-button" type="submit">Save Vehicle</button></footer></form></dialog><dialog class="fleet-action-dialog" data-fleet-action-dialog><form data-fleet-action-form><header><div><p class="eyebrow">Fleet operations</p><h3 data-fleet-action-title>Action</h3></div><button type="button" data-close-fleet-action aria-label="Close">×</button></header><div data-fleet-action-fields></div><footer><p data-fleet-action-status role="status"></p><button class="secondary-button" type="button" data-close-fleet-action>Cancel</button><button class="primary-button" type="submit">Save</button></footer></form></dialog>`);document.querySelectorAll("[data-close-fleet-dialog]").forEach(b=>b.addEventListener("click",()=>document.querySelector("[data-fleet-vehicle-dialog]").close()));document.querySelectorAll("[data-close-fleet-action]").forEach(b=>b.addEventListener("click",()=>document.querySelector("[data-fleet-action-dialog]").close()));document.querySelector("[data-fleet-vehicle-form]").addEventListener("submit",saveVehicle);document.querySelector("[data-fleet-action-form]").addEventListener("submit",saveAction);}
function field(label,name,type="text",value="",extra=""){return `<label>${label}<input name="${name}" type="${type}" value="${escapeHtml(value??"")}" ${extra}></label>`;}
function selectField(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${escapeHtml(v)}" ${String(value)===String(v)?"selected":""}>${escapeHtml(l)}</option>`;}).join("")}</select></label>`;}
function vehicleFormHtml(v={}){const p=v.partner||{};return `<section><div class="fleet-form-section-title"><b>1</b><div><h3>Basic Information</h3><p>Customer-safe listing details.</p></div></div><div class="fleet-form-grid">${field("Year","year","number",v.year,"min=1900 max=2100 required")}${field("Make","make","text",v.make,"required")}${field("Model","model","text",v.model,"required")}${field("Trim","trim","text",v.trim)}${selectField("Category","category",CATEGORIES.map(x=>[x.toLowerCase().replaceAll(" ","-"),x]),v.category)}${field("Exterior Color","color","text",v.color)}${field("Interior Color","interior_color","text",v.interior_color)}${field("Seats","seats","number",v.seats||2,"min=1 max=12")}${field("Internal nickname","internal_nickname","text",v.internal_nickname)}<label class="wide">Description<textarea name="summary" rows="3">${escapeHtml(v.summary||"")}</textarea></label></div></section><section><div class="fleet-form-section-title"><b>2</b><div><h3>Identification</h3><p>Private operational identifiers.</p></div></div><div class="fleet-form-grid">${field("VIN","vin","text",v.vin)}${field("License Plate","license_plate","text",v.license_plate)}${field("State","registration_state","text",v.registration_state||"CA")}${field("Internal Fleet ID","internal_fleet_id","text",v.internal_fleet_id)}</div></section><section><div class="fleet-form-section-title"><b>3</b><div><h3>Ownership</h3><p>Owned and partner inventory use the same fleet record.</p></div></div><div class="fleet-form-grid">${selectField("Ownership","ownership_type",[["prestige","Prestige Owned"],["partner","Partner Vehicle"]],v.ownership_type||"prestige")}${selectField("Operational status","operational_status",[["available","Available"],["maintenance","Maintenance"],["on_hold","On Hold"],["partner_unavailable","Partner Unavailable"],["inactive","Inactive / Archived"]],v.operational_status||"available")}<div class="wide fleet-partner-fields" data-partner-fields>${field("Existing Partner Name","partner_name","text",p.partner_name)}${field("Partner Phone","partner_phone","tel",p.partner_phone)}${field("Partner Vehicle ID","partner_identifier","text",p.partner_identifier)}<label>Partner notes<textarea name="partner_notes" rows="3">${escapeHtml(p.partner_notes||"")}</textarea></label></div></div></section><section><div class="fleet-form-section-title"><b>4</b><div><h3>Customer Pricing</h3><p>Defaults carry into new quotes and can still be overridden.</p></div></div><div class="fleet-form-grid">${field("Standard Daily Rate","price","number",v.price||0,"min=0 step=.01 required")}${field("Weekend Rate","weekend_rate","number",v.weekend_rate,"min=0 step=.01")}${field("Weekly Rate","weekly_rate","number",v.weekly_rate,"min=0 step=.01")}${field("Hourly Rate","hourly_rate","number",v.hourly_rate,"min=0 step=.01")}${field("Event / Wedding Rate","event_rate","number",v.event_rate,"min=0 step=.01")}${field("Included Mileage / Day","included_mileage","number",v.included_mileage,"min=0")}${field("Extra Mileage Rate","extra_mileage_rate","number",v.extra_mileage_rate,"min=0 step=.01")}${field("Refundable Security Deposit","security_deposit","number",v.security_deposit,"min=0 step=.01")}${field("Minimum Rental Days","minimum_rental_days","number",v.minimum_rental_days||1,"min=1")}${field("Delivery Base Fee","delivery_base_fee","number",v.delivery_base_fee,"min=0 step=.01")}</div></section><section data-partner-pricing><div class="fleet-form-section-title"><b>5</b><div><h3>Partner Pricing</h3><p>Internal only. Never shown to customers.</p></div></div><div class="fleet-form-grid">${field("Partner Daily Cost","partner_daily_cost","number",p.partner_daily_cost,"min=0 step=.01")}${field("Weekend Cost","weekend_cost","number",p.weekend_cost,"min=0 step=.01")}${field("Weekly Cost","weekly_cost","number",p.weekly_cost,"min=0 step=.01")}${field("Minimum Partner Charge","minimum_partner_charge","number",p.minimum_partner_charge,"min=0 step=.01")}${field("Delivery Cost","delivery_cost","number",p.delivery_cost,"min=0 step=.01")}${field("Other Partner Fees","other_partner_fees","number",p.other_partner_fees,"min=0 step=.01")}</div></section><section><div class="fleet-form-section-title"><b>6</b><div><h3>Vehicle Photos</h3><p>Upload and reorder. The first photo is the cover.</p></div></div><div class="fleet-photo-editor" data-fleet-photo-editor>${(v.photos||[]).map((ph,i)=>photoRow(ph.url,i)).join("")||photoRow("",0)}</div><button class="secondary-button compact" type="button" data-add-fleet-photo>Add Photo</button></section><section><div class="fleet-form-section-title"><b>7</b><div><h3>Mileage & Location</h3><p>Current operating snapshot; rental history stays untouched.</p></div></div><div class="fleet-form-grid">${field("Current Mileage","current_mileage","number",v.current_mileage,"min=0")}${selectField("Mileage Source","mileage_source",[["manual","Manual"],["service","Service"],["rental_checkin","Rental Check-in"]],v.mileage_source||"manual")}${selectField("Current Location","current_location",LOCATIONS,v.current_location||LOCATIONS[0])}<label>Location Notes<textarea name="location_notes" rows="3">${escapeHtml(v.location_notes||"")}</textarea></label></div></section><section><div class="fleet-form-section-title"><b>8</b><div><h3>Registration & Insurance</h3><p>Private staff-only expiration tracking.</p></div></div><div class="fleet-form-grid">${field("Registration Expiration","registration_expiration","date",v.registration_expiration)}${field("Insurance Provider","insurance_provider","text",v.insurance_provider)}${field("Policy Number","insurance_policy_number","text",v.insurance_policy_number)}${field("Insurance Expiration","insurance_expiration","date",v.insurance_expiration)}</div></section>`;}
function simpleVehicleFormHtml(v={}){const p=v.partner||{};return `<section><div class="fleet-form-section-title"><b>1</b><div><h3>Vehicle Details</h3><p>Only the information needed to list and quote the car.</p></div></div><div class="fleet-form-grid">${field("Vehicle Name","name","text",v.name,"required")}${field("Make","make","text",v.make,"required")}${field("Model","model","text",v.model,"required")}${selectField("Category","category",CATEGORIES.map(x=>[x.toLowerCase().replaceAll(" ","-"),x]),v.category)}${field("Exterior Color","color","text",v.color)}${field("Seats","seats","number",v.seats||2,"min=1 max=12")}<label class="wide">Description<textarea name="summary" rows="3">${escapeHtml(v.summary||"")}</textarea></label></div></section><section><div class="fleet-form-section-title"><b>2</b><div><h3>Pricing</h3><p>Simple defaults used when creating a quote.</p></div></div><div class="fleet-form-grid">${field("Daily Rate","price","number",v.price||0,"min=0 step=.01 required")}${field("Mileage Allowance","mileage","text",v.mileage||"100 miles/day")}</div></section><section><div class="fleet-form-section-title"><b>3</b><div><h3>Ownership</h3><p>Choose whether Prestige Luxor or a partner supplies the vehicle.</p></div></div><div class="fleet-form-grid">${selectField("Ownership","ownership_type",[["prestige","Prestige Luxor"],["partner","Partner Vehicle"]],v.ownership_type||"prestige")}<div class="wide fleet-partner-fields" data-partner-fields>${field("Partner Name","partner_name","text",p.partner_name)}${field("Partner Phone","partner_phone","tel",p.partner_phone)}</div></div></section><section><div class="fleet-form-section-title"><b>4</b><div><h3>Vehicle Photos</h3><p>Upload, remove, and reorder photos. The first photo is the cover.</p></div></div><div class="fleet-photo-editor" data-fleet-photo-editor>${(v.photos||[]).map((ph,i)=>photoRow(ph.url,i)).join("")||photoRow("",0)}</div><button class="secondary-button compact" type="button" data-add-fleet-photo>Add Photo</button></section>`;}
function photoRow(url,i){return `<article data-fleet-photo-row><img src="${escapeHtml(url||"/assets/prestige-luxor-hero.png")}" alt="Photo ${i+1}" width="150" height="90"><input type="hidden" name="photo_url" value="${escapeHtml(url)}"><label>Photo ${i+1}${i===0?" · Cover":""}<input type="file" accept="image/*" data-fleet-photo-file></label><div><button type="button" data-move-fleet-photo="-1" aria-label="Move photo up">↑</button><button type="button" data-move-fleet-photo="1" aria-label="Move photo down">↓</button><button type="button" data-remove-fleet-photo aria-label="Remove photo">×</button></div></article>`;}
function togglePartner(form){const isPartner=form.elements.ownership_type.value==="partner";const fields=form.querySelector("[data-partner-fields]"),pricing=form.querySelector("[data-partner-pricing]");if(fields)fields.hidden=!isPartner;if(pricing)pricing.hidden=!isPartner;}
function openVehicleForm(v=null){ensureDialogs();const dialog=document.querySelector("[data-fleet-vehicle-dialog]"),form=dialog.querySelector("form");form.dataset.vehicleId=v?.id||"";dialog.querySelector("[data-fleet-form-title]").textContent=v?`Edit ${vehicleTitle(v)}`:"Add Vehicle";dialog.querySelector("[data-fleet-form-fields]").innerHTML=simpleVehicleFormHtml(v||{});dialog.querySelector("[data-fleet-form-status]").textContent="";form.elements.ownership_type.addEventListener("change",()=>togglePartner(form));togglePartner(form);form.querySelector("[data-add-fleet-photo]").addEventListener("click",()=>form.querySelector("[data-fleet-photo-editor]").insertAdjacentHTML("beforeend",photoRow("",form.querySelectorAll("[data-fleet-photo-row]").length)));form.querySelector("[data-fleet-photo-editor]").addEventListener("click",photoControls);form.querySelector("[data-fleet-photo-editor]").addEventListener("change",previewPhoto);dialog.showModal();}
function photoControls(e){const row=e.target.closest("[data-fleet-photo-row]");if(!row)return;if(e.target.closest("[data-remove-fleet-photo]")){row.remove();return;}const move=e.target.closest("[data-move-fleet-photo]");if(!move)return;const sibling=Number(move.dataset.moveFleetPhoto)<0?row.previousElementSibling:row.nextElementSibling;if(sibling)row.parentElement.insertBefore(Number(move.dataset.moveFleetPhoto)<0?row:sibling,Number(move.dataset.moveFleetPhoto)<0?sibling:row);}
function previewPhoto(e){if(!e.target.matches("[data-fleet-photo-file]"))return;const file=e.target.files[0];if(file)e.target.closest("article").querySelector("img").src=URL.createObjectURL(file);}
async function uploadFleetPhotos(form,vehicleId,slug){const rows=[...form.querySelectorAll("[data-fleet-photo-row]")],urls=[];for(let i=0;i<rows.length;i++){const file=rows[i].querySelector("[data-fleet-photo-file]").files[0];let url=rows[i].querySelector('[name="photo_url"]').value;if(file){const path=`${slug||vehicleId}/${String(i+1).padStart(2,"0")}-${Date.now()}-${file.name.replace(/[^a-z0-9.]+/gi,"-")}`;const {error}=await window.prestigeLuxorSupabase.storage.from(SUPABASE_STORAGE_BUCKET).upload(path,file,{upsert:true});if(error)throw error;url=window.prestigeLuxorSupabase.storage.from(SUPABASE_STORAGE_BUCKET).getPublicUrl(path).data.publicUrl;}if(url)urls.push({url});}await api("fleet",{method:"POST",body:JSON.stringify({action:"photos",car_id:vehicleId,photos:urls})});}
async function saveVehicle(e){e.preventDefault();const form=e.currentTarget,status=form.querySelector("[data-fleet-form-status]"),body=Object.fromEntries(new FormData(form));body.action="vehicle";body.id=form.dataset.vehicleId||undefined;body.car_id=form.dataset.vehicleId||undefined;body.is_active=body.operational_status!=="inactive";try{status.textContent="Saving vehicle…";const response=await api("fleet",{method:form.dataset.vehicleId?"PATCH":"POST",body:JSON.stringify(body)});await uploadFleetPhotos(form,response.vehicle.id,response.vehicle.slug);form.closest("dialog").close();toast(form.dataset.vehicleId?"Vehicle updated.":"Vehicle added to the fleet.");await load(true);await openVehicle(response.vehicle.id);}catch(error){status.textContent=error.message;status.dataset.tone="error";}}

function actionFields(type,v){const now=new Date(),tomorrow=new Date(now.getTime()+86400000);if(type==="block")return `${selectField("Block Type","block_type",[["manual_hold","Manual Hold"],["owner_use","Owner using vehicle"],["maintenance","Maintenance"],["photoshoot","Photoshoot"],["partner_unavailable","Partner unavailable"],["other","Other"]],"manual_hold")}${field("Starts","start_at","datetime-local",localInput(now),"required")}${field("Ends","end_at","datetime-local",localInput(tomorrow),"required")}${field("Reason","reason","text","","required")}<label>Notes<textarea name="notes" rows="3"></textarea></label>`;if(type==="expense")return `${selectField("Expense Scope","expense_scope",[["general","General vehicle expense"],["reservation","Reservation-specific expense"]],"general")}${selectField("Category","category",EXPENSE_TYPES,"other")}${field("Amount","amount","number","","min=0 step=.01 required")}${field("Date","expense_date","date",today(),"required")}${field("Vendor","vendor")}${field("Reservation ID (optional)","agreement_id")}<label>Notes<textarea name="notes" rows="3"></textarea></label>`;if(type==="maintenance")return `${selectField("Service Type","service_type",SERVICE_TYPES,"Oil Service")}${selectField("Status","status",[["scheduled","Scheduled"],["in_service","In Service"],["completed","Completed"],["cancelled","Cancelled"]],"completed")}${field("Service Date","service_date","date",today(),"required")}${field("Mileage","mileage","number",v.current_mileage,"min=0")}${field("Vendor","vendor")}${field("Cost","cost","number","","min=0 step=.01")}${field("Next Service Date","next_service_date","date")}${field("Next Service Mileage","next_service_mileage","number","","min=0")}${field("Unavailable From","unavailable_start","datetime-local")}${field("Unavailable Until","unavailable_end","datetime-local")}<label>Notes<textarea name="notes" rows="3"></textarea></label>`;if(type==="document")return `${selectField("Document Type","document_type",DOC_TYPES.map(x=>[x,x.replaceAll("_"," ")]),"registration")}${field("File","document_file","file","",'accept="application/pdf,image/*"')}${field("Effective Date","effective_date","date")}${field("Expiration Date","expiration_date","date")}<label>Notes<textarea name="notes" rows="3"></textarea></label>`;return `${field("Current Mileage","mileage","number",v.current_mileage,"min=0 required")}${selectField("Source","source",[["manual","Manual"],["service","Service"],["rental_checkin","Rental Check-in"]],"manual")}`;}
function openAction(type,defaults={}){if(!selected)return;ensureDialogs();const dialog=document.querySelector("[data-fleet-action-dialog]"),form=dialog.querySelector("form");form.reset();form.dataset.action=type;dialog.querySelector("[data-fleet-action-title]").textContent={block:"Block Dates",expense:"Add Vehicle Expense",maintenance:"Add Maintenance",document:"Add Vehicle Document",mileage:"Update Mileage"}[type];dialog.querySelector("[data-fleet-action-fields]").innerHTML=actionFields(type,selected);dialog.querySelector("[data-fleet-action-status]").textContent="";for(const[k,v]of Object.entries(defaults))if(form.elements[k])form.elements[k].value=v;dialog.showModal();}
async function uploadPrivate(file,vehicleId,type){if(!file)return null;const path=`vehicles/${vehicleId}/${type}-${Date.now()}-${file.name.replace(/[^a-z0-9.]+/gi,"-")}`;const {error}=await window.prestigeLuxorSupabase.storage.from("rental-documents").upload(path,file,{upsert:false});if(error)throw error;return path;}
async function saveAction(e){e.preventDefault();const form=e.currentTarget,type=form.dataset.action,status=form.querySelector("[data-fleet-action-status]"),body=Object.fromEntries(new FormData(form)),vehicleId=selected.id;body.action=type;body.car_id=vehicleId;try{status.textContent="Saving…";if(type==="document"){const file=form.elements.document_file?.files[0];body.file_path=await uploadPrivate(file,vehicleId,body.document_type);body.file_name=file?.name||"";delete body.document_file;}await api("fleet",{method:"POST",body:JSON.stringify(body)});form.closest("dialog").close();toast(`${type[0].toUpperCase()+type.slice(1)} saved.`);await load(true);await openVehicle(vehicleId);detailTab=type==="expense"?"financials":type==="block"?"calendar":type==="document"?"documents":type==="maintenance"?"maintenance":"overview";renderDetail();}catch(error){status.textContent=error.message;status.dataset.tone="error";}}

async function load(force=false){if(loaded&&!force){renderMain();return;}if(!data.vehicles.length){const instant=instantVehicles();if(instant.length){data={vehicles:instant,role:"staff",period:{key:period,start:new Date().toISOString(),end:new Date().toISOString()}};renderMain();}}try{const fresh=await api(`fleet?period=${period}`);data=fresh;loaded=true;if(selected){const updated=data.vehicles.find(vehicle=>String(vehicle.id)===String(selected.id));if(updated){selected=updated;detailData={...detailData,vehicle:updated};renderDetail();}}else renderMain();}catch(error){if(data.vehicles.length){toast(`Fleet details are still syncing: ${error.message}`,"error");return;}root.innerHTML=`<div class="fleet-error"><strong>Fleet needs attention</strong><p>${escapeHtml(error.message)}</p><button class="secondary-button" data-retry-fleet>Retry</button></div>`;}}

root?.addEventListener("input",e=>{if(e.target.matches("[data-fleet-search]")){filter.search=e.target.value;renderMain();const input=root.querySelector("[data-fleet-search]");input?.focus();input?.setSelectionRange(filter.search.length,filter.search.length);}});
root?.addEventListener("change",async e=>{if(e.target.matches("[data-fleet-filter]")){filter[e.target.dataset.fleetFilter]=e.target.value;renderMain();}if(e.target.matches("[data-fleet-period]")){period=e.target.value;await load(true);}});
root?.addEventListener("click",async e=>{const ownership=e.target.closest("[data-fleet-ownership]");if(ownership){filter.ownership=ownership.dataset.fleetOwnership;return renderMain();}const viewButton=e.target.closest("[data-fleet-view]");if(viewButton){view=viewButton.dataset.fleetView;localStorage.setItem("prestige-fleet-view",view);return renderMain();}const range=e.target.closest("[data-calendar-range]");if(range){calendarRange=Number(range.dataset.calendarRange);localStorage.setItem("prestige-fleet-calendar-range",calendarRange);return selected?renderDetail():renderMain();}if(e.target.closest("[data-retry-fleet]"))return load(true);if(e.target.closest("[data-back-fleet]"))return renderMain();if(e.target.closest("[data-fleet-add-inline]"))return openVehicleForm();const tab=e.target.closest("[data-vehicle-tab]");if(tab){detailTab=tab.dataset.vehicleTab;return renderDetail();}const reservation=e.target.closest("[data-open-reservation]");if(reservation){document.querySelector('[data-crm-section="agreements"]')?.click();window.dispatchEvent(new CustomEvent("prestige:open-agreement",{detail:{id:reservation.dataset.openReservation}}));return;}const cell=e.target.closest("[data-calendar-cell]");if(cell&&!cell.dataset.openReservation){const id=cell.dataset.calendarCell;if(!selected||selected.id!==id)await openVehicle(id);return openAction("block",{start_at:`${cell.dataset.date}T09:00`,end_at:`${cell.dataset.date}T18:00`});}const open=e.target.closest("[data-open-vehicle]");if(open)return openVehicle(open.dataset.openVehicle);const action=e.target.closest("[data-fleet-action]");if(action){const type=action.dataset.fleetAction;if(type==="edit")return openVehicleForm(selected);if(type==="quote"){document.querySelector('[data-crm-section="requests"]')?.click();window.dispatchEvent(new CustomEvent("prestige:new-quote-for-vehicle",{detail:{vehicle:selected}}));return;}return openAction(type);}const del=e.target.closest("[data-delete-fleet-record]");if(del){if(!confirm(`Remove this ${del.dataset.deleteFleetRecord} record?`))return;try{await api(`fleet?type=${del.dataset.deleteFleetRecord}&id=${del.dataset.recordId}&car_id=${selected.id}`,{method:"DELETE"});toast("Fleet record removed.");await load(true);await openVehicle(selected.id);detailTab="calendar";renderDetail();}catch(error){toast(error.message,"error");}}const doc=e.target.closest("[data-open-document]");if(doc){try{const {data:signed,error}=await window.prestigeLuxorSupabase.storage.from("rental-documents").createSignedUrl(doc.dataset.openDocument,120);if(error)throw error;window.open(signed.signedUrl,"_blank","noopener");}catch(error){toast(error.message,"error");}}});
root?.addEventListener("keydown",e=>{const row=e.target.closest("[data-open-vehicle]");if(row&&["Enter"," "].includes(e.key)){e.preventDefault();openVehicle(row.dataset.openVehicle);}});
addButton?.addEventListener("click",()=>openVehicleForm());calendarButton?.addEventListener("click",()=>{view="calendar";localStorage.setItem("prestige-fleet-view",view);loaded?renderMain():load();});nav?.addEventListener("click",()=>load());window.prestigeLuxorSupabase?.auth.onAuthStateChange((event,session)=>{if(!session)loaded=false;else if(document.querySelector('[data-section-panel="vehicles"]')?.classList.contains("active"))load();});
ensureDialogs();

function syncArchiveAction(){const search=root?.querySelector("[data-fleet-search]");if(search)search.placeholder="Make, model, category, or partner";const actions=root?.querySelector(".fleet-detail-nav>div");if(!actions||!selected?.is_active||actions.querySelector('[data-fleet-action="archive"]'))return;const button=document.createElement("button");button.type="button";button.className="secondary-button compact danger";button.dataset.fleetAction="archive";button.textContent="Archive";actions.insertBefore(button,actions.lastElementChild);}
new MutationObserver(syncArchiveAction).observe(root,{childList:true,subtree:true});
root?.addEventListener("click",async e=>{if(!e.target.closest('[data-fleet-action="archive"]'))return;e.preventDefault();e.stopImmediatePropagation();if(!selected||!confirm(`Archive ${vehicleTitle(selected)}? Its rental and financial history will be preserved.`))return;try{const vehicleId=selected.id;await api("fleet",{method:"POST",body:JSON.stringify({action:"archive",car_id:vehicleId})});toast("Vehicle archived. History was preserved.");await load(true);}catch(error){toast(error.message,"error");}},true);
